.ds-btn { display: inline-flex; align-items: center; gap: 6px; padding: 8px 16px; border-radius: 12px; font-size: 13px; font-weight: 500; font-family: Poppins, -apple-system, "Segoe UI", Roboto, sans-serif; cursor: pointer; border: none; transition: background 0.13s, color 0.13s; }
.ds-btn:disabled { opacity: 0.55; cursor: not-allowed; }
.ds-btn-primary { background: var(--theme-accent, #c9a84c); color: var(--theme-accent-text, #0f1117); font-weight: 700; }
.ds-btn-primary:hover:not(:disabled) { background: var(--theme-accent-hover, #d4b96a); }
.ds-btn-primary:focus-visible { outline: none; box-shadow: 0 0 0 3px var(--theme-focus-ring, rgba(201,168,76,0.15)); }

.ds-btn { display: inline-flex; align-items: center; gap: 6px; padding: 8px 16px; border-radius: 12px; font-size: 13px; font-weight: 500; font-family: Poppins, -apple-system, "Segoe UI", Roboto, sans-serif; cursor: pointer; border: none; transition: background 0.13s, color 0.13s; }
.ds-btn:disabled { opacity: 0.55; cursor: not-allowed; }
.ds-btn-ghost { background: var(--theme-input-bg, #0f1117); color: var(--theme-text1, #e8e0d0); border: 1px solid var(--theme-border-lt, #1e2330); }
.ds-btn-ghost:hover:not(:disabled) { background: var(--theme-table-hover, rgba(255,255,255,0.03)); border-color: var(--theme-accent, #c9a84c); }
.ds-btn-ghost:focus-visible { outline: none; box-shadow: 0 0 0 3px var(--theme-focus-ring, rgba(201,168,76,0.15)); }

.ds-btn { display: inline-flex; align-items: center; gap: 6px; padding: 8px 16px; border-radius: 12px; font-size: 13px; font-weight: 500; font-family: Poppins, -apple-system, "Segoe UI", Roboto, sans-serif; cursor: pointer; border: none; transition: background 0.13s, color 0.13s; }
.ds-btn:disabled { opacity: 0.55; cursor: not-allowed; }
.ds-btn-danger { background: var(--theme-input-bg, #0f1117); color: var(--theme-red, #f87171); border: 1px solid rgba(248,113,113,0.45); }
.ds-btn-danger:hover:not(:disabled) { background: rgba(248,113,113,0.12); border-color: var(--theme-red, #f87171); }

.ds-danger-row { display: flex; gap: 10px; flex-wrap: wrap; }
.ds-btn { display: inline-flex; align-items: center; gap: 6px; padding: 8px 16px; border-radius: 12px; font-size: 13px; font-weight: 500; font-family: Poppins, -apple-system, "Segoe UI", Roboto, sans-serif; cursor: pointer; border: none; transition: background 0.13s, color 0.13s; }
.ds-btn:disabled { opacity: 0.55; cursor: not-allowed; }
.ds-btn-danger { background: var(--theme-input-bg, #0f1117); color: var(--theme-red, #f87171); border: 1px solid rgba(248,113,113,0.45); }
.ds-btn-danger:hover:not(:disabled) { background: rgba(248,113,113,0.12); border-color: var(--theme-red, #f87171); }
.ds-btn-danger-strong { background: rgba(248,113,113,0.16); border-color: rgba(248,113,113,0.55); font-weight: 700; }
.ds-btn-danger-strong:hover:not(:disabled) { background: rgba(248,113,113,0.24); border-color: var(--theme-red, #f87171); }

.ds-badge { display: inline-block; padding: 2px 8px; border-radius: 8px; font-size: 11px; font-weight: 500; text-transform: capitalize; font-family: Poppins, -apple-system, "Segoe UI", Roboto, sans-serif; }
.ds-badge-green { background: rgba(52,211,153,0.10); color: var(--theme-green, #34d399); }
.ds-badge-amber { background: rgba(251,191,36,0.12); color: var(--theme-amber, #fbbf24); }
.ds-badge-red { background: rgba(248,113,113,0.10); color: var(--theme-red, #f87171); }
.ds-badge-gray { background: rgba(138,146,163,0.10); color: var(--theme-text2, #8a92a3); }

.ds-card { background: var(--theme-card, #181c27); border: 1px solid var(--theme-border, #2a2f3d); border-radius: 18px; box-shadow: inset 0 1px 0 0 rgba(232,224,208,0.06), 0 10px 24px -8px rgba(15,17,23,0.55), 0 3px 8px -3px rgba(15,17,23,0.4); padding: 24px; font-family: Poppins, -apple-system, "Segoe UI", Roboto, sans-serif; }
.ds-card-title { font-size: 15px; font-weight: 600; color: var(--theme-text1, #e8e0d0); margin-bottom: 8px; }
.ds-card-body { font-size: 13px; line-height: 1.5; color: var(--theme-text3, #9ca3af); margin: 0; }

.ds-stat-card { background: var(--theme-card, #181c27); border: 1px solid var(--theme-border, #2a2f3d); border-radius: 18px; box-shadow: inset 0 1px 0 0 rgba(232,224,208,0.06), 0 10px 24px -8px rgba(15,17,23,0.55), 0 3px 8px -3px rgba(15,17,23,0.4); padding: 20px; font-family: Poppins, -apple-system, "Segoe UI", Roboto, sans-serif; }
.ds-stat-label { font-size: 11px; font-weight: 500; letter-spacing: 0.08em; text-transform: uppercase; color: var(--theme-text3, #9ca3af); margin-bottom: 6px; }
.ds-stat-value { font-size: 24px; font-weight: 700; color: var(--theme-text1, #e8e0d0); }

.ds-field { display: flex; flex-direction: column; gap: 4px; font-family: Poppins, -apple-system, "Segoe UI", Roboto, sans-serif; }
.ds-label { font-size: 11px; font-weight: 500; letter-spacing: 0.08em; text-transform: uppercase; color: var(--theme-text3, #9ca3af); }
.ds-input { background: var(--theme-input-bg, #0f1117); border: 1px solid var(--theme-border, #2a2f3d); border-radius: 12px; padding: 8px 12px; font-size: 13px; font-family: inherit; color: var(--theme-text1, #e8e0d0); outline: none; }
.ds-input::placeholder { color: var(--theme-text2, #8a92a3); }
.ds-input:focus { border-color: var(--theme-accent, #c9a84c); box-shadow: 0 0 0 3px var(--theme-focus-ring, rgba(201,168,76,0.15)); }
.ds-input[aria-invalid="true"] { border-color: var(--theme-red, #f87171); }

.ds-tab-bar { display: flex; gap: 8px; font-family: Poppins, -apple-system, "Segoe UI", Roboto, sans-serif; }
.ds-tab { appearance: none; background: var(--theme-card, #181c27); border: 1px solid var(--theme-border, #2a2f3d); border-radius: 12px; padding: 4px 12px; font-size: 12px; font-weight: 500; font-family: inherit; color: var(--theme-text2, #8a92a3); cursor: pointer; transition: color 0.12s, border-color 0.12s, background 0.12s; }
.ds-tab:hover { color: var(--theme-text1, #e8e0d0); border-color: rgba(201,168,76,0.25); }
.ds-tab-active { color: var(--theme-accent, #c9a84c); border-color: rgba(201,168,76,0.5); background: var(--theme-focus-ring, rgba(201,168,76,0.15)); font-weight: 600; }

.ds-panel-tabs { display: flex; flex-wrap: wrap; gap: 2px; padding: 0 18px; border-bottom: 1px solid var(--theme-border, #2a2f3d); font-family: Poppins, -apple-system, "Segoe UI", Roboto, sans-serif; }
.ds-panel-tab { background: none; border: none; cursor: pointer; padding: 11px 14px; min-height: 40px; font-size: 13px; font-weight: 400; font-family: inherit; white-space: nowrap; color: var(--theme-text2, #8a92a3); border-bottom: 2px solid transparent; margin-bottom: -1px; transition: color 160ms cubic-bezier(0.4,0,0.2,1), border-color 160ms cubic-bezier(0.4,0,0.2,1); }
.ds-panel-tab:hover { color: var(--theme-text1, #e8e0d0); }
.ds-panel-tab:focus-visible { outline: none; color: var(--theme-accent, #c9a84c); box-shadow: 0 0 0 3px var(--theme-focus-ring, rgba(201,168,76,0.15)); }
.ds-panel-tab-active { color: var(--theme-accent, #c9a84c); border-bottom-color: var(--theme-accent, #c9a84c); font-weight: 600; }
.ds-panel-tab-danger, .ds-panel-tab-danger:hover { color: var(--theme-red, #f87171); }
.ds-panel-tab-danger.ds-panel-tab-active { border-bottom-color: var(--theme-red, #f87171); }

.ds-table-wrap { overflow-x: auto; font-family: Poppins, -apple-system, "Segoe UI", Roboto, sans-serif; }
.ds-table { width: 100%; border-collapse: collapse; font-size: 13px; }
.ds-table th { text-align: left; padding: 10px 5px; color: var(--theme-text2, #8a92a3); font-weight: 500; font-size: 11px; letter-spacing: 0.08em; text-transform: uppercase; border-bottom: 1px solid var(--theme-border, #2a2f3d); white-space: nowrap; }
.ds-table td { padding: 11px 5px; color: var(--theme-text1, #e8e0d0); border-bottom: 1px solid var(--theme-border-lt, #1e2330); }
.ds-table tr:last-child td { border-bottom: none; }
.ds-table tbody tr:hover td { background: var(--theme-table-hover, rgba(255,255,255,0.03)); }
.ds-num { text-align: right; white-space: nowrap; }
.ds-badge { display: inline-block; padding: 2px 8px; border-radius: 8px; font-size: 11px; font-weight: 500; }
.ds-badge-amber { background: rgba(251,191,36,0.12); color: var(--theme-amber, #fbbf24); }
.ds-badge-green { background: rgba(52,211,153,0.10); color: var(--theme-green, #34d399); }
.ds-row-btn { background: var(--theme-input-bg, #0f1117); border: 1px solid var(--theme-border-lt, #1e2330); border-radius: 12px; padding: 4px 10px; margin-left: 6px; font-size: 11px; font-family: inherit; cursor: pointer; transition: background 0.13s, border-color 0.13s; }
.ds-row-approve { color: var(--theme-green, #34d399); }
.ds-row-reject { color: var(--theme-red, #f87171); }
.ds-row-btn:hover { border-color: currentColor; }

.ds-nav { display: flex; flex-direction: column; background: var(--theme-sidebar, #0e1117); padding: 8px 0; font-family: Poppins, -apple-system, "Segoe UI", Roboto, sans-serif; }
.ds-nav-link { display: flex; align-items: center; gap: 10px; margin: 1px 10px; padding: 8px 12px; border-radius: 12px; font-size: 13px; color: var(--theme-text2, #8a92a3); text-decoration: none; white-space: nowrap; transition: color 160ms cubic-bezier(0.4,0,0.2,1), background 160ms cubic-bezier(0.4,0,0.2,1); }
.ds-nav-link:hover { color: var(--theme-text1, #e8e0d0); background: var(--theme-table-hover, rgba(255,255,255,0.03)); }
.ds-nav-link-active { color: var(--theme-accent, #c9a84c); background: var(--theme-focus-ring, rgba(201,168,76,0.15)); font-weight: 600; }

.ds-report-error { font-family: Poppins, -apple-system, "Segoe UI", Roboto, sans-serif; padding: 20px 24px; border-radius: 18px; border: 1px solid var(--theme-red, #f87171); background: color-mix(in srgb, var(--theme-red, #f87171) 8%, var(--theme-card, #181c27)); }
.ds-report-error-title { font-size: 15px; font-weight: 600; color: var(--theme-red-text, #f87171); margin-bottom: 6px; }
.ds-report-error-body { font-size: 13px; color: var(--theme-text1, #e8e0d0); margin: 0 0 8px; }
.ds-report-error-hint { font-size: 12px; color: var(--theme-text2, #8a92a3); margin: 0; line-height: 1.6; }

.ds-form-input { font-family: Poppins, -apple-system, "Segoe UI", Roboto, sans-serif; width: 100%; box-sizing: border-box; background: var(--theme-input-bg, #0f1117); border: 1px solid var(--theme-border, #2a2f3d); border-radius: 12px; padding: 8px 12px; font-size: 13px; color: var(--theme-text1, #e8e0d0); }
.ds-form-input::placeholder { color: var(--theme-text3, #9ca3af); }
.ds-form-input:focus { outline: none; border-color: var(--theme-accent, #c9a84c); box-shadow: 0 0 0 3px var(--theme-focus-ring, rgba(201,168,76,0.15)); }
.ds-form-input:focus-visible { outline: 2px solid var(--theme-focus-outline, #c9a84c); outline-offset: 1px; }

.ds-table { font-family: Poppins, -apple-system, "Segoe UI", Roboto, sans-serif; width: 100%; border-collapse: collapse; font-size: 13px; font-variant-numeric: tabular-nums; color: var(--theme-text1, #e8e0d0); }
.ds-table td { padding: 11px 5px; border-bottom: 1px solid var(--theme-border-lt, #1e2330); }
.ds-num { text-align: right; }
.ds-table tfoot td { border-top: 2px solid var(--theme-border, #2a2f3d); border-bottom: none; font-weight: 700; padding-top: 12px; }
.ds-table tfoot tr:hover td { background: transparent; }

.ds-field { font-family: Poppins, -apple-system, "Segoe UI", Roboto, sans-serif; }
.ds-field-label { display: block; font-size: 11px; font-weight: 500; letter-spacing: 0.08em; text-transform: uppercase; color: var(--theme-text2, #8a92a3); margin-bottom: 6px; }
.ds-chips { display: flex; gap: 6px; flex-wrap: wrap; }
.ds-chip { font-family: inherit; background: var(--theme-card, #181c27); border: 1px solid var(--theme-border, #2a2f3d); border-radius: 12px; padding: 6px 12px; font-size: 12px; color: var(--theme-text2, #8a92a3); cursor: pointer; }
.ds-chip-on { color: var(--theme-accent-ink, #c9a84c); font-weight: 600; border-color: color-mix(in srgb, var(--theme-accent, #c9a84c) 50%, transparent); background: var(--theme-focus-ring, rgba(201,168,76,0.15)); }
.ds-chip:focus-visible { outline: 2px solid var(--theme-focus-outline, #c9a84c); outline-offset: 2px; }

.ds-wrap { overflow-x: auto; font-family: Poppins, -apple-system, "Segoe UI", Roboto, sans-serif; }
.ds-mtx { width: 100%; border-collapse: collapse; font-size: 13px; font-variant-numeric: tabular-nums; color: var(--theme-text1, #e8e0d0); }
.ds-mtx th { text-align: left; padding: 10px 5px; font-size: 11px; font-weight: 500; letter-spacing: 0.08em; text-transform: uppercase; color: var(--theme-text2, #8a92a3); border-bottom: 1px solid var(--theme-border, #2a2f3d); white-space: nowrap; }
.ds-mtx td { padding: 11px 5px; border-bottom: 1px solid var(--theme-border-lt, #1e2330); }
.ds-mtx .ds-num { text-align: right; }
.ds-mtx th:first-child, .ds-mtx td:first-child { position: sticky; left: 0; z-index: 1; background: var(--theme-card, #181c27); }

.ds-disc-tbl { font-family: Poppins, -apple-system, "Segoe UI", Roboto, sans-serif; width: 100%; border-collapse: collapse; font-size: 13px; font-variant-numeric: tabular-nums; color: var(--theme-text1, #e8e0d0); }
.ds-disc-tbl td { padding: 11px 5px; border-bottom: 1px solid var(--theme-border-lt, #1e2330); }
.ds-disc-num { text-align: right; }
.ds-row-disclosure { -webkit-appearance: none; appearance: none; background: none; border: none; padding: 2px 4px; margin: -2px -4px; font: inherit; color: inherit; line-height: 1; cursor: pointer; border-radius: 4px; }
.ds-row-disclosure:hover { color: var(--theme-accent-ink, #c9a84c); }
.ds-row-disclosure:focus-visible { outline: 2px solid var(--theme-focus-outline, #c9a84c); outline-offset: 1px; background: var(--theme-focus-ring, rgba(201,168,76,0.15)); }
